package com.example.dealership.document;

import java.net.URI;
import java.util.List;

import jakarta.validation.Valid;

import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestMapping;
import org.springframework.web.bind.annotation.RestController;
import org.springframework.web.servlet.support.ServletUriComponentsBuilder;

@RestController
@RequestMapping("/api/vehicles/{vehicleId}/documents")
public class VehicleDocumentController {

    private final VehicleDocumentService vehicleDocumentService;

    public VehicleDocumentController(VehicleDocumentService vehicleDocumentService) {
        this.vehicleDocumentService = vehicleDocumentService;
    }

    @GetMapping
    public List<DocumentResponse> findAll(@PathVariable Long vehicleId) {
        return vehicleDocumentService.findAll(vehicleId);
    }

    @GetMapping("/{documentId}")
    public DocumentResponse findById(@PathVariable Long vehicleId, @PathVariable Long documentId) {
        return vehicleDocumentService.findById(vehicleId, documentId);
    }

    @PostMapping
    public ResponseEntity<DocumentResponse> create(@PathVariable Long vehicleId,
            @Valid @RequestBody DocumentRequest request) {
        DocumentResponse response = vehicleDocumentService.create(vehicleId, request);
        URI location = ServletUriComponentsBuilder.fromCurrentRequest()
                .path("/{documentId}")
                .buildAndExpand(response.id())
                .toUri();
        return ResponseEntity.created(location).body(response);
    }
}
